inline const IQC *GetIQC(const void *buf) {
  return ::flatbuffers::GetRoot<IQC>(buf);
}

inline const IQC *GetSizePrefixedIQC(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<IQC>(buf);
}

inline const char *IQCIdentifier() {
  return "$IQC";
}

inline bool IQCBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, IQCIdentifier());
}

inline bool SizePrefixedIQCBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, IQCIdentifier(), true);
}

template <bool B = false>
inline bool VerifyIQCBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<IQC>(IQCIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedIQCBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<IQC>(IQCIdentifier());
}

inline void FinishIQCBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<IQC> root) {
  fbb.Finish(root, IQCIdentifier());
}

inline void FinishSizePrefixedIQCBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<IQC> root) {
  fbb.FinishSizePrefixed(root, IQCIdentifier());
}

